int pin1 = 12;
int pin2 = 11;

void setup() {
  pinMode(pin1, OUTPUT);
  pinMode(pin2, INPUT);
  Serial.begin(9600);
}

void loop() {
  if(digitalRead(pin2)==1) {
    digitalWrite(pin1, LOW);
  }
  else if(digitalRead(pin2)==0) {
    digitalWrite(pin1, HIGH);
  }
}

