#include <EEPROM.h>

int pin = 13;

void setup() {
  pinMode(pin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  for (int i = 0; i < EEPROM.length(); i++) {
    EEPROM.write(i, 1);
  }
  digitalWrite(pin, HIGH);
  exit(0);
}

